import{_ as r,a as e,c as a,ac as o}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅 · 49 革：变化需要信任与时机至51 震：惊惧之后恢复分寸","description":"核读古籍，理解变革与建立、震动与止息、婚姻礼制、丰盛及羁旅处境。","frontmatter":{"title":"六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅 · 49 革：变化需要信任与时机至51 震：惊惧之后恢复分寸","description":"核读古籍，理解变革与建立、震动与止息、婚姻礼制、丰盛及羁旅处境。","splitFrom":"life/personal/yijing/hexagrams-49-56.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅","summary":"核读古籍，理解变革与建立、震动与止息、婚姻礼制、丰盛及羁旅处境。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅","link":"/life/personal/yijing/hexagrams-49-56"},"next":{"text":"六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅 · 52 艮：止在适当之处至54 归妹：看见关系中的位置与代价","link":"/life/personal/yijing/hexagrams-49-56-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅","link":"/life/personal/yijing/hexagrams-49-56"},"next":{"text":"六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅 · 52 艮：止在适当之处至54 归妹：看见关系中的位置与代价","link":"/life/personal/yijing/hexagrams-49-56-part-02"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-49-56-part-01.md","filePath":"life/personal/yijing/hexagrams-49-56-part-01.md"}'),n={name:"life/personal/yijing/hexagrams-49-56-part-01.md"};function d(s,t,i,p,l,g){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="六十四卦详读-四十九至五十六-革、鼎、震、艮、渐、归妹、丰、旅-·-49-革-变化需要信任与时机至51-震-惊惧之后恢复分寸" tabindex="-1">六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅 · 49 革：变化需要信任与时机至51 震：惊惧之后恢复分寸 <a class="header-anchor" href="#六十四卦详读-四十九至五十六-革、鼎、震、艮、渐、归妹、丰、旅-·-49-革-变化需要信任与时机至51-震-惊惧之后恢复分寸" aria-label="Permalink to &quot;六十四卦详读（四十九至五十六）：革、鼎、震、艮、渐、归妹、丰、旅 · 49 革：变化需要信任与时机至51 震：惊惧之后恢复分寸&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-49-56">返回分篇目录</a></p><p>这里保留《周易》卦辞、爻辞与《象传》大象的原貌，再用简体中文解释。白话均为现代概括，古注主要取王弼注、孔颖达疏《周易正义》，不是现代逐字译文。遇到异文、难字或不同解释时会注明；引文中的占断属于古代文本，不据以保证事件结果。</p><p>这八卦既有革鼎的制度变化，也有震艮的动静，更有渐、归妹中的婚姻礼制。读古代家庭与政治时，要同时看见思想资源和历史限制；现代借鉴必须说明转换的前提。</p><h2 id="六十四卦详读-四十九至五十六" tabindex="-1">六十四卦详读（四十九至五十六） <a class="header-anchor" href="#六十四卦详读-四十九至五十六" aria-label="Permalink to &quot;六十四卦详读（四十九至五十六） {#六十四卦详读-四十九至五十六}&quot;">​</a></h2><p>这里保留《周易》卦辞、爻辞与《象传》大象的原貌，再用简体中文解释。白话均为现代概括，古注主要取王弼注、孔颖达疏《周易正义》，不是现代逐字译文。遇到异文、难字或不同解释时会注明；引文中的占断属于古代文本，不据以保证事件结果。</p><p>这八卦既有革鼎的制度变化，也有震艮的动静，更有渐、归妹中的婚姻礼制。读古代家庭与政治时，要同时看见思想资源和历史限制；现代借鉴必须说明转换的前提。</p><h2 id="gua-49" tabindex="-1">49 革：变化需要信任与时机 <a class="header-anchor" href="#gua-49" aria-label="Permalink to &quot;49 革：变化需要信任与时机 {#gua-49}&quot;">​</a></h2><p><strong>卦符：䷰｜上卦兑 ☱（泽），下卦离 ☲（火）。</strong> 水火相处而互相作用，《彖传》由此说明变化。革原有皮革义，经文与古注又把它展开为改变。</p><p><strong>卦辞原文：</strong></p><blockquote><p>革：已日乃孚，元亨。利貞。悔亡。</p></blockquote><p><strong>白话概括：</strong> 改变不是一开始就得到相信，要有合宜的过程和可见的结果。《正义》文本有“己、巳”等字形，释为变革当日未信、经过以后才信；其他读法会联系纪日，不能据一字确定吉日。古注的重点是“革而当”：变化适当，才谈得上悔亡，而非变化本身就有价值。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九</td><td>鞏用黃牛之革。</td><td>如用坚韧牛革牢固约束，变革之初尚不能轻动；“革”的皮革实物义在这里仍清晰可见。</td></tr><tr><td>六二</td><td>已日乃革之，征吉，无咎。</td><td>待时机形成再参与改变，行动才可成立；古注强调与九五相应，不是等待一个固定天数。</td></tr><tr><td>九三</td><td>征凶，貞厲，革言三就，有孚。</td><td>强行继续推进有险；关于“三就”，《正义》解释为上三爻已从革成言，不能再以强征求服。</td></tr><tr><td>九四</td><td>悔亡，有孚改命，吉。</td><td>改变命令或制度有信任支持，才得其吉；把信任作为条件，而非改完再要求别人无条件相信。</td></tr><tr><td>九五</td><td>大人虎變，未占有孚。</td><td>如虎纹鲜明，变化已清楚可见，不待占问而有信；虎变是显著改变的比喻，不是化身神异。</td></tr><tr><td>上六</td><td>君子豹變，小人革面，征凶，居貞吉。</td><td>深层改变与表面顺从并存；此时再征进反凶，应进入稳定阶段，不能把反复运动当作目的。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>澤中有火，革；君子以治歷明時。</p></blockquote><p><strong>大象解释：</strong> 整理历法，辨明时序。变化需要识别周期与时机，这里的历法工作本来就是古代治理活动，不能直接替代现代科学历法。</p><p><strong>整体读法与误区：</strong> 革不是“凡旧必坏、凡新必好”。从初九的未动到上六的停止追进，文本同时讨论发动与收束。《彖传》的“汤武革命”指王命更替，其概念不能与所有现代革命直接等同。日常可借来问：旧办法为何不适用，受影响者是否知情，效果如何验证，何时结束过渡；这些问题比用卦名宣称改革必成更可靠。</p><p><strong>经传对读：</strong> 虎变、豹变与革面并列，使变化具有不同深度和可见程度；但不能仅凭外表断言某人只是假装改变。经文在上六仍要求停止征进，说明变革收束后需给新秩序稳定的空间。可以把初九的约束和上六的居贞放在两端，观察中间如何围绕信任逐步展开。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9D%A9" target="_blank" rel="noopener noreferrer">《周易·革》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/05%E9%9D%A9" target="_blank" rel="noopener noreferrer">《周易正义》卷五·革</a>。</p><h2 id="gua-50" tabindex="-1">50 鼎：把改变落实为供养与秩序 <a class="header-anchor" href="#gua-50" aria-label="Permalink to &quot;50 鼎：把改变落实为供养与秩序 {#gua-50}&quot;">​</a></h2><p><strong>卦符：䷱｜上卦离 ☲（火），下卦巽 ☴（木）。</strong> 木助火而烹饪，鼎既是炊器，也是礼器；卦中足、腹中食物、耳、铉都可以在实物上找到位置。</p><p><strong>卦辞原文：</strong></p><blockquote><p>鼎：元吉，亨。</p></blockquote><p><strong>白话概括：</strong> 鼎取成新之义，大吉而通达。《正义》把它接在革后理解：变革之后，必须形成器用、法度与供养方式；若只有变化而没有制度，仍会生乱。其尊卑安排属于古代政治，现代可保留“建立稳定承载”的问题，不必照搬等级体系。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初六</td><td>鼎顛趾，利出否，得妾以其子，无咎。</td><td>暂时倒鼎以清除旧污，反常动作因清理目的而可理解；“得妾以其子”保留古代婚姻继嗣背景。</td></tr><tr><td>九二</td><td>鼎有實，我仇有疾，不我能即，吉。</td><td>鼎内有食，近旁关系却有问题而不能来近；“仇”有匹配、相对者之义，不必径译成仇敌。</td></tr><tr><td>九三</td><td>鼎耳革，其行塞，雉膏不食，方雨虧悔，終吉。</td><td>鼎耳有变而搬运受阻，美食不能享用；待关系调和，缺憾可减，说明有内容仍需畅通的使用条件。</td></tr><tr><td>九四</td><td>鼎折足，覆公餗，其形渥，凶。</td><td>鼎足折断，公家食物倾覆，污沾其身；“形／刑”有异文，古注重在承担重任却失其支撑。</td></tr><tr><td>六五</td><td>鼎黃耳金鉉，利貞。</td><td>黄色鼎耳与金属举鼎之器相配，象征居中而能接纳刚健支撑；“铉”是穿鼎耳举鼎的器具。</td></tr><tr><td>上九</td><td>鼎玉鉉，大吉，无不利。</td><td>玉铉兼取坚实与温润，《小象》强调刚柔有节；不是说昂贵器物天然带来好运。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>木上有火，鼎；君子以正位凝命。</p></blockquote><p><strong>大象解释：</strong> 使职责位置端正，使命令、使命凝定。《正义》解释“凝”为严整，重在变革之后的秩序和稳定承担。</p><p><strong>整体读法与误区：</strong> 可用“食物能否真正供养人”串联六爻：旧污要清，已有食物要守，搬运要通，支脚要稳，举鼎之具要合适。这样的器物阅读比只背“鼎新”更具体。现代借鉴涉及职责、能力和公共资源，尤其要注意九四：承重失配会损及他人。文本没有授权把组织里的人按贵贱评定价值，所谓“正位”也须接受现代权利与公平原则的检验。</p><p><strong>经传对读：</strong> 鼎的足负责承重，耳与铉负责举移，食物是供养内容；几种功能不能互相替代。九三食物精美却不能食，九四则因承重失败而连食物一起丧失，这两种失效原因不同。把具体器物先画清楚，再读古注的政治类比，能减少把鼎的每一部分都抽象成同一种“能力”的含混。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%BC%8E" target="_blank" rel="noopener noreferrer">《周易·鼎》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/05%E9%BC%8E" target="_blank" rel="noopener noreferrer">《周易正义》卷五·鼎</a>。</p><h2 id="gua-51" tabindex="-1">51 震：惊惧之后恢复分寸 <a class="header-anchor" href="#gua-51" aria-label="Permalink to &quot;51 震：惊惧之后恢复分寸 {#gua-51}&quot;">​</a></h2><p><strong>卦符：䷲｜上卦震 ☳，下卦震 ☳，两雷相继。</strong> 这是八个重卦之一，震兼有雷、动、惊的意义；卦象是文本比喻，不是地震预报模型。</p><p><strong>卦辞原文：</strong></p><blockquote><p>震：亨。震來虩虩，笑言啞啞。震驚百里，不喪匕鬯。</p></blockquote><p><strong>白话概括：</strong> 震动来临先惊惧，后来恢复言笑；剧烈震惊中仍不失祭礼的匕与香酒。“虩虩”写恐惧，“啞啞”写笑声，“鬯”读 chàng。《正义》强调由惊而警醒、保持所守，背景包含继承宗庙责任，而非要求任何人天生不怕危险。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九</td><td>震來虩虩，後笑言啞啞，吉。</td><td>有惊惧也有恢复，能从冲击中找到行为准则；恐惧本身不必被羞辱。</td></tr><tr><td>六二</td><td>震來厲，億喪貝，躋于九陵，勿逐，七日得。</td><td>危急时可能丢失财物、登高避险，不急于追索；“亿”训释有异，“七日”保留占辞而不作现实期限。</td></tr><tr><td>六三</td><td>震蘇蘇，震行无眚。</td><td>受惊而神情不安，因警醒调整行动可免灾；“眚”读 shěng，指过失或灾害。</td></tr><tr><td>九四</td><td>震遂泥。</td><td>震动却陷在泥滞中，不能有效作为；不是所有激烈反应都能带来实际改变。</td></tr><tr><td>六五</td><td>震往來厲，億无喪，有事。</td><td>冲击往来都有危险，仍须顾住所承担的事；“无丧”应结合保全职责理解，不保证财物毫无损失。</td></tr><tr><td>上六</td><td>震索索，視矍矍，征凶。震不于其躬，于其鄰，无咎。婚媾有言。</td><td>惊惶失措时贸然行动有险；从邻近发生的事中先受警戒，可少过，但亲近关系可能仍有怨言。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>洊雷，震；君子以恐懼修省。</p></blockquote><p><strong>大象解释：</strong>“洊”是相继，雷声反复使人省察。将恐惧转为检查与修正，是这里的伦理方向；不需要把长期焦虑美化为德行。</p><p><strong>整体读法与误区：</strong> 本卦同时有笑、失财、泥滞、职责和人际反应，展示惊动后的多种状态。现代可借来讨论应急准备与事后复盘，先保护生命，再整理资源和责任；“不丧匕鬯”不意味着危险中必须保护物品。对“百里、九陵、七日”应先读其文本作用，不据数字推断灾害范围、地点或日期。</p><p><strong>经传对读：</strong> 初九的恐惧能够转为有则，上六却在视觉和行动上持续惊乱，区别不在是否有情绪，而在能否恢复判断。九四的泥滞和六五的有事又提示，外部震动并不必然改变内部停滞。阅读时可以把受到的冲击、出现的情绪和随后的行动分成三列，避免只用“勇敢”概括整卦。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E9%9C%87" target="_blank" rel="noopener noreferrer">《周易·震》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/05%E9%9C%87" target="_blank" rel="noopener noreferrer">《周易正义》卷五·震</a>。</p>',46)])])}const u=r(n,[["render",d]]);export{c as __pageData,u as default};
